typedef float rational_t;
typedef int axis_id_t;

enum PS2_Axes
{
  JOY_PS2_DX,
  JOY_PS2_DY,
  JOY_PS2_X,
  JOY_PS2_Y,
  JOY_PS2_LX,
  JOY_PS2_LY,
  JOY_PS2_BTNL3,
  JOY_PS2_RX,
  JOY_PS2_RY,
  JOY_PS2_BTNR3,
  JOY_PS2_BTNX,
  JOY_PS2_BTNO,
  JOY_PS2_DUMMMY1,
  JOY_PS2_BTNSQ,
  JOY_PS2_BTNTR,
  JOY_PS2_DUMMMY2,
  JOY_PS2_BTNL1,
  JOY_PS2_BTNR1,
  JOY_PS2_BTNL2,
  JOY_PS2_BTNR2,
  JOY_PS2_START,
  JOY_PS2_SELECT,
  JOY_PS2_DISCONNECT,
  JOY_PS2_NUM_AXES
};

#define PS2_JOYPAD_DUALSHOCK (char)0x73
#define PS2_JOYPAD_DUALSHOCK2 (char)0x79
#define JOY_STICK_DEADZONE 50.0f
#define assert(x) ((void)0)

extern "C" float __fabs(float);

class ps2_joypad_device
{
  char data[0x66];
  signed char pad_type;
public:
  rational_t get_axis_state(axis_id_t axis, unsigned char *rdata) const;
};

rational_t ps2_joypad_device::get_axis_state( axis_id_t axis, unsigned char *rdata ) const
{
 rational_t dpad, astick;
 switch (axis)
 {
 case JOY_PS2_X:
  dpad = get_axis_state((axis_id_t)JOY_PS2_DX, rdata);
  astick = get_axis_state((axis_id_t)JOY_PS2_LX, rdata);
  if (__fabs(astick) > __fabs(dpad)) return astick;
  return dpad;
 case JOY_PS2_Y:
  dpad = get_axis_state((axis_id_t)JOY_PS2_DY, rdata);
  astick = get_axis_state((axis_id_t)JOY_PS2_LY, rdata);
  if (__fabs(astick) > __fabs(dpad)) return astick;
  return dpad;
 case JOY_PS2_DX:
  if ((rdata[2] & (unsigned char)0x80) == 0) return -1.0f;
  else if ((rdata[2] & (unsigned char)0x20) == 0) return 1.0f;
  return 0.0f;
 case JOY_PS2_DY:
  if ((rdata[2] & (unsigned char)0x40) == 0) return 1.0f;
  else if ((rdata[2] & (unsigned char)0x10) == 0) return -1.0f;
  return 0.0f;
 case JOY_PS2_LX:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) {
   float tmp = rdata[6] - 127.0f;
   if (tmp < -JOY_STICK_DEADZONE || tmp > JOY_STICK_DEADZONE) return ((rational_t)tmp)/127.0f;
   else return 0.0f;
  } else return 0.0f;
 case JOY_PS2_LY:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) {
   float tmp = rdata[7] - 127.0f;
   if (tmp < -JOY_STICK_DEADZONE || tmp > JOY_STICK_DEADZONE) return ((rational_t)tmp)/127.0f;
   else return 0.0f;
  } else return 0.0f;
 case JOY_PS2_BTNL3:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) { if ((rdata[2] & (unsigned char)0x02) == 0) return 1.0f; }
  return 0.0f;
 case JOY_PS2_RX:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) return ((rational_t)rdata[4] - 127.0f)/127.0f;
  else return 0.0f;
 case JOY_PS2_RY:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) return ((rational_t)rdata[5] - 127.0f)/127.0f;
  else return 0.0f;
 case JOY_PS2_BTNR3:
  if (pad_type == PS2_JOYPAD_DUALSHOCK || pad_type == PS2_JOYPAD_DUALSHOCK2) { if ((rdata[2] & (unsigned char)0x04) == 0) return 1.0f; }
  return 0.0f;
 case JOY_PS2_BTNX: if ((rdata[3] & (unsigned char)0x40) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNO: if ((rdata[3] & (unsigned char)0x20) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNR1: if ((rdata[3] & (unsigned char)0x08) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNSQ: if ((rdata[3] & (unsigned char)0x80) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNTR: if ((rdata[3] & (unsigned char)0x10) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNL2: if ((rdata[3] & (unsigned char)0x01) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNL1: if ((rdata[3] & (unsigned char)0x04) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_BTNR2: if ((rdata[3] & (unsigned char)0x02) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_START: if ((rdata[2] & (unsigned char)0x08) == 0) return 1.0f; return 0.0f;
 case JOY_PS2_SELECT: if ((rdata[2] & (unsigned char)0x01) == 0) return 1.0f; return 0.0f;
 default:
  assert("ps2_joypad_device::get_axis_state illegal axis queried." == 0);
  return 0.0f;
 }
}
